import React, { useCallback, useEffect, useMemo, useState } from "react";
import { useNavigate } from "react-router-dom";

import BookingList from "../components/BookingList";
import BookingForm from "../components/BookingForm";
import InchargeModal from "../components/InchargeModal";
import Navbar from "../components/Navbar";
import RejectModal from "../components/RejectModal";
import Sidebar from "../components/Sidebar";
import { useAppContext } from "../context/AppContext";
import api from "../services/api";

const initialStats = {
  total: 0,
  pending: 0,
  approved: 0,
  rejected: 0,
};

const ClientDashboard = ({ view = "overview" }) => {
  const navigate = useNavigate();
  const { incharges, fetchInitialData } = useAppContext();

  const [bookings, setBookings] = useState([]);
  const [stats, setStats] = useState(initialStats);
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [initialLoadDone, setInitialLoadDone] = useState(false);

  const [showIncharges, setShowIncharges] = useState(false);
  const [cancelBookingId, setCancelBookingId] = useState(null);

  // ✅ FORM STATE
  const [formData, setFormData] = useState({
    resourceScope: "block",
    blockId: "",
    resourceId: "",
    name: "",
    department: "",
    bookingDate: "",
    startTime: "",
    endTime: "",
    purpose: "",
  });

  // ✅ HANDLERS
  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({
      ...prev,
      [name]: value,
    }));
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    console.log("FORM DATA:", formData);
    alert("Booking Created (check console)");
  };

  const handleAvailabilityCheck = () => {
    console.log("Check availability:", formData);
  };

  // ✅ MENU
  const menuItems = useMemo(
    () => [
      { key: "overview", label: "Overview", to: "/", icon: "🏠" },
      { key: "new-booking", label: "New Booking", to: "/new-booking", icon: "➕" },
      { key: "my-bookings", label: "My Bookings", to: "/my-bookings", icon: "📋" },
      { key: "incharges", label: "Incharges", icon: "👨‍💼" },
    ],
    []
  );

  const handleLogout = useCallback(() => {
    localStorage.clear();
    navigate("/login");
  }, [navigate]);

  // 🔥 FIXED FETCH
  const fetchDashboard = useCallback(async () => {
    try {
      if (!initialLoadDone) setLoading(true);

      const [dashboardRes, bookingsRes] = await Promise.all([
        api.get("/client/dashboard"),
        api.get("/client/bookings"),
      ]);

      // 🔥 DEBUG
      console.log("Dashboard API:", dashboardRes.data);

      const data = dashboardRes.data || {};

      // ✅ SAFE MAPPING (MAIN FIX)
      setStats({
        total: data.total || data.total_bookings || 0,
        pending: data.pending || data.pending_bookings || 0,
        approved: data.approved || data.approved_bookings || 0,
        rejected: data.rejected || data.rejected_bookings || 0,
      });

      setBookings(bookingsRes.data || []);
      setError("");
    } catch (err) {
      if (err.response?.status === 401) {
        localStorage.clear();
        navigate("/login");
        return;
      }

      console.log("ERROR:", err);
      setError(err.message || "Server error");
    } finally {
      setLoading(false);
      setInitialLoadDone(true);
    }
  }, [initialLoadDone, navigate]);

  useEffect(() => {
    fetchDashboard();
    fetchInitialData?.();
  }, [fetchDashboard, fetchInitialData]);

  const handleRefresh = async () => {
    setRefreshing(true);
    await fetchDashboard();
    setRefreshing(false);
  };

  const handleCancel = (id) => {
    setCancelBookingId(id);
  };

  const handleCancelSubmit = async (reason) => {
    try {
      await api.post(`/client/bookings/${cancelBookingId}/cancel`, { reason });
      setCancelBookingId(null);
      fetchDashboard();
    } catch {
      alert("Cancel failed");
    }
  };

  const recentBookings = useMemo(() => bookings.slice(0, 3), [bookings]);

  // ✅ VIEW RENDER
  const renderContent = () => {
    switch (view) {
      case "new-booking":
        return (
          <BookingForm
            formData={formData}
            onChange={handleChange}
            onSubmit={handleSubmit}
            onAvailabilityCheck={handleAvailabilityCheck}
          />
        );

      case "my-bookings":
        return (
          <BookingList
            title="My Bookings"
            bookings={bookings}
            onCancel={handleCancel}
          />
        );

      default:
        return (
          <>
            {/* ✅ STATS FIXED */}
            <section className="stats-grid">
              <div className="card"><p>Total</p><h2>{stats.total}</h2></div>
              <div className="card"><p>Pending</p><h2>{stats.pending}</h2></div>
              <div className="card"><p>Approved</p><h2>{stats.approved}</h2></div>
              <div className="card"><p>Rejected</p><h2>{stats.rejected}</h2></div>
            </section>

            <BookingList
              title="Recent Bookings"
              bookings={recentBookings}
              onCancel={handleCancel}
            />
          </>
        );
    }
  };

  return (
    <div className="dashboard-shell">
      <Sidebar
        role="Client"
        items={menuItems}
        onLogout={handleLogout}
        onSelect={(key) => key === "incharges" && setShowIncharges(true)}
      />

      <main className="dashboard-main">
        <Navbar
          title="Client Dashboard"
          onRefresh={handleRefresh}
          refreshing={refreshing}
        />

        {error && <div className="error-box">{error}</div>}

        {loading && !initialLoadDone ? <p>Loading...</p> : renderContent()}
      </main>

      <InchargeModal
        open={showIncharges}
        groups={incharges}
        onClose={() => setShowIncharges(false)}
      />

      <RejectModal
        open={Boolean(cancelBookingId)}
        onClose={() => setCancelBookingId(null)}
        onSubmit={handleCancelSubmit}
      />
    </div>
  );
};

export default ClientDashboard;
